import { useState } from 'react';

export default function {{component_name}}() {
  const [data, setData] = useState({ name: '', email: '', message: '' });
  const [sent, setSent] = useState(false);

  async function onSubmit(e: React.FormEvent) {
    e.preventDefault();
    await fetch('{{endpoint}}', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(data),
    });
    setSent(true);
  }

  if (sent) return <p>Thanks, we will get back to you.</p>;

  return (
    <form onSubmit={onSubmit}>
      <input value={data.name} onChange={(e) => setData({ ...data, name: e.target.value })} placeholder="Name" required />
      <input type="email" value={data.email} onChange={(e) => setData({ ...data, email: e.target.value })} placeholder="Email" required />
      <textarea value={data.message} onChange={(e) => setData({ ...data, message: e.target.value })} placeholder="Message" required />
      <button type="submit">Send</button>
    </form>
  );
}
